import collections,re
def parse(path):
    names={}
    own=collections.defaultdict(collections.Counter)
    edges=collections.Counter()
    function,callee=None,None
    inclusive=False
    events=None
    summary=None
    for line in path.read_text().splitlines():
        if line.startswith('events:'):
            events=line.split()[1:]
        elif line.startswith('summary:'):
            summary=dict(zip(events,map(int,line.split()[1:])))
        match=re.match(r'(c?fn)=\((\d+)\)(?: (.*))?$',line)
        if match:
            kind,number,name=match.groups()
            if name is not None:
                names[number]=name
            if kind=='fn':
                function=number
            else:
                callee=number
        elif line.startswith('calls='):
            edges[(function,callee)]+=int(line.split()[0].split('=')[1])
            inclusive=True
        elif re.match(r'^(0x[0-9a-f]+|[+-]\d+|\*) ',line):
            if inclusive:
                inclusive=False
            else:
                own[function].update(dict(zip(events,map(int,line.split()[1:]))))
    assert summary is not None
    assert sum(counts['Ir'] for counts in own.values())==summary['Ir']
    return {'summary':summary,'self_counts':{names[k]:dict(v) for k,v in own.items()},'calls':{names[a]+' -> '+names[b]:n for (a,b),n in edges.items()}}
